insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-makaron-z-makiem', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-makaron-z-makiem/8433ad1c-f5da-46b5-841e-6ae4a4a27692.webp', 15, 20, 4, null, null, '{}'::jsonb, '', array['post-wigilia', 'post-makowiec-technik', 'post-ersatzprodukte-de']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-makaron-z-makiem', 'de', 'Makaron z makiem', 'makaron-z-makiem', 'Gekochte Nudeln mit Mohn, Butter und Zucker, eine klassische süße Wigilia-Speise, die sich klar von der Makowiec-Rolle und vom Makaron z serem unterscheidet.', '[{"text":"Kurze Eiernudeln oder Bandnudeln in reichlich Salzwasser al dente kochen, abgießen und etwas Nudelwasser zurückhalten.","tip":"Das ist Pasta aus dem Topf, keine Hefe-Mohnrolle wie [Makowiec](/de/rezepte/makowiec). Den Menürahmen dafür liefert der [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan)."},{"text":"Mohn (blau, möglichst gemahlen) mit heißer Milch oder Wasser kurz aufquellen lassen, abtropfen, dann mit Zucker, geschmolzener Butter und optional Honig, Rosinen und Zitronenschale zu einer streichfähigen, nicht tropfenden Masse rühren.","tip":"Frisch gemahlenen Mohn findest du für den Feiertagseinkauf oft im [Polenladen](/de/blog/polenladen-einkaufen). Wie sich die Masse anfühlen soll, zeigt auch der [Makowiec-Technik](/de/blog/makowiec-technik)-Guide, auch wenn hier keine Rolle entsteht, sondern Nudeln mit Mohn."},{"text":"Heiße Nudeln mit der Mohnmasse und Butter vermengen, bei Bedarf einen Schuss Nudelwasser für mehr Bindung zugeben. Abschmecken, bis es süß und mohnig, aber nicht bitter schmeckt.","tip":"Twaróg gehört hier nicht hinein, das wäre [Makaron z serem](/de/rezepte/makaron-z-serem). Fehlt Mohn oder eine andere Zutat, hilft der Beitrag zu [Ersatzprodukten DE](/de/blog/ersatzprodukte-de) weiter."},{"text":"Sofort warm servieren, auf Tellern, optional mit Puderzucker bestäubt. Reste schmecken kalt oder kurz in der Pfanne mit etwas Butter aufgewärmt.","tip":"Bleibt vom Mohn noch etwas übrig, lässt sich daraus am nächsten Tag ganz einfach eine kleine zweite Portion Nudeln mit Mohn zaubern, statt die Masse wegzuwerfen."}]'::jsonb, 'Makaron z makiem, süß und mohnig, butterweich, festlich und trotzdem in einer knappen Stunde aus dem Topf. Mohn gehört seit vorchristlicher Zeit zur Wigilia, denn seine schlaffördernde Wirkung galt als Brücke zwischen der Welt der Lebenden und der der Ahnen, die in der Winterzeit um den Heiligabend als besonders nah galt. Eine Mohnkapsel trägt über tausend winzige Samen, deshalb stand Mohn zusätzlich für Fülle, Fruchtbarkeit und Wohlstand im kommenden Jahr. Makaron z makiem, gekochte Nudeln mit süßer Mohnmasse, ist die regionale Antwort auf diese Symbolik aus Wielkopolska, Kujawy und der Gegend um Łódź, also aus Gebieten, die einst zur preußischen Teilung gehörten. Dort übernahm diese Nudelspeise die Rolle, die im Osten Polens die [Kutia](/de/rezepte/kutia) aus Weizenkörnern spielt. Ganz bewusst ist das keine gerollte Hefeteig-Spezialität wie [Makowiec](/de/rezepte/makowiec), dessen Technik der [Makowiec-Technik](/de/blog/makowiec-technik)-Guide erklärt, und auch kein Quarkgericht wie [Makaron z serem](/de/rezepte/makaron-z-serem).

## Einkaufen und kochen

Kurze Eiernudeln oder Bandnudeln bekommst du im Supermarkt, dazu Butter, Zucker und Milch. Der eigentliche Geschmacksträger ist blauer, möglichst frisch gemahlener Mohn, den du oft im [Polenladen](/de/blog/polenladen-einkaufen) findest. Ganze Mohnsamen lassen sich auch selbst mahlen, das dann aber ehrlich so kennzeichnen. Optional passen Honig, Rosinen und Zitronenschale dazu. Fehlt gemahlener Mohn, hilft der Beitrag zu [Ersatzprodukten DE](/de/blog/ersatzprodukte-de) weiter, allerdings sollte kein Kakao als Mohnersatz herhalten.

Die Nudeln sollten al dente bleiben, während der Mohn kurz in heißer Flüssigkeit aufquillt und danach gut abtropft. Mit Zucker und Butter verrührt entsteht daraus eine streichfähige Masse, die weder tropft noch trocken und sandig wirkt. Alles heiß vermengen, denn kalte Nudeln nehmen den Geschmack schlechter an, und Nudelwasser nur sparsam zugeben, sonst verwässert die Masse. Bitterkeit stammt fast immer von altem Mohn oder zu starkem Rösten, deshalb lohnt sich ein Blick auf das Herstellungsdatum. Anders als beim [Makowiec](/de/rezepte/makowiec) gibt es hier keinen Rollschritt und keinen Ofengang, das Gericht ist fertig, sobald alles im Topf vermengt ist.

In deutschen Küchen rettet Makaron z makiem oft den 24. Dezember, wenn der Ofen schon mit anderen Gerichten belegt ist und niemand mehr Hefeteig führen möchte: ein Topf Nudeln, eine Schüssel Mohnmasse, fertig. Mohn hältst du am besten aus dem [Polenladen](/de/blog/polenladen-einkaufen) vorrätig, Kinder dürfen streuen und rühren, während der heiße Topf bei den Erwachsenen bleibt. Gute Standardnudeln und frischer Mohn reichen völlig aus, ein Nachbar zur Technik der Mohnmasse steht im [Makowiec-Technik](/de/blog/makowiec-technik)-Guide.

## Am Tisch

Warm auf Tellern, oft mit Puderzucker bestäubt, als süßer Gang am [Wigilia](/de/blog/wigilia-speiseplan)-Tisch neben Kompot und Fisch. Klar getrennt bleiben davon Scheiben mit Spirale, das ist [Makowiec](/de/rezepte/makowiec), und cremige Pasta mit Quark, das ist [Makaron z serem](/de/rezepte/makaron-z-serem). Reste schmecken kalt oder kurz in Butter aufgewärmt in der Pfanne, ein erneutes hartes Kochen sollte man ihnen ersparen.

Wer Makaron z makiem mit der gerollten [Makowiec](/de/rezepte/makowiec)-Rolle verwechselt, erwartet fälschlich einen Hefekuchen statt einer Nudelspeise. Ebenso führt eine Verwechslung mit [Makaron z serem](/de/rezepte/makaron-z-serem) in die falsche Richtung, denn dort dominiert Quark statt Mohn. Zu trockene, sandige Masse entsteht meist durch zu wenig Flüssigkeit, während alter, bitterer Mohn den ganzen Geschmack kippen kann. Zu viel Nudelwasser wiederum macht aus der cremigen Masse schnell eine Suppe.

Mehr Honig macht die Masse runder im Geschmack, Rosinen bleiben die klassische Zutat, und Orangenschale statt Zitrone gibt eine mildere Note. Kalt schmeckt die Speise am Folgetag fast wie ein Dessert. Die Mohnrolle bleibt [Makowiec](/de/rezepte/makowiec), Pasta mit Quark ist [Makaron z serem](/de/rezepte/makaron-z-serem), und Weizenkörner mit Mohn statt Nudeln findest du bei [Kutia](/de/rezepte/kutia). Zum Anlass passt der [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan), zur Mohnmasse die [Makowiec-Technik](/de/blog/makowiec-technik), und Einkaufshilfen liefern der [Polenladen](/de/blog/polenladen-einkaufen) und die [Ersatzprodukte](/de/blog/ersatzprodukte-de).', 'Makaron z makiem Rezept | Nudeln mit Mohn | Alemniam', 'Makaron z makiem: Nudeln mit Mohn, Butter und Zucker. Wigilia-tauglich, bilingual, klar getrennt von Makowiec und Makaron z serem.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-makaron-z-makiem', 'pl', 'Makaron z makiem', 'makaron-z-makiem', 'Ugotowany makaron z makiem, masłem i cukrem, klasyczna słodka potrawa wigilijna, wyraźnie inna niż rolada makowiec i niż makaron z serem.', '[{"text":"Ugotuj krótki makaron jajeczny lub wstążki al dente w osolonej wodzie, odcedź i zostaw odrobinę wody z gotowania.","tip":"To makaron z garnka, a nie drożdżowa rolada jak [makowiec](/pl/rezepte/makowiec). Ramę menu daje [menu wigilijne](/pl/blog/menu-wigilijne)."},{"text":"Mak (niebieski, najlepiej mielony) zalej gorącym mlekiem lub wodą, odsącz, potem wymieszaj z cukrem, roztopionym masłem oraz opcjonalnie miodem, rodzynkami i skórką cytryny na smarowną, nie cieknącą masę.","tip":"Świeżo mielony mak na świąteczne zakupy znajdziesz często w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Jak powinna wyglądać dobra masa, pokazuje też [technika makowca](/pl/blog/makowiec-technika), choć tu nie powstaje rolada, tylko makaron z makiem."},{"text":"Wymieszaj gorący makaron z masą makową i masłem, w razie potrzeby dodaj odrobinę wody z gotowania dla lepszego związania. Dopraw, aż będzie słodko i makowo, bez goryczy.","tip":"Twaróg tu nie pasuje, to byłby [makaron z serem](/pl/rezepte/makaron-z-serem). Jeśli brakuje maku lub innego składnika, pomogą [zamienniki składników](/pl/blog/zamienniki-skladnikow)."},{"text":"Podawaj od razu na ciepło, na talerzach, opcjonalnie z cukrem pudrem. Resztki smakują na zimno albo krótko podgrzane na patelni z odrobiną masła.","tip":"Jeśli zostanie trochę masy makowej, następnego dnia łatwo zrobisz z niej kolejną małą porcję makaronu z makiem, zamiast ją wyrzucać."}]'::jsonb, 'Makaron z makiem, słodko-makowy, maślany, świąteczny, a mimo to gotowy w niecałą godzinę z garnka. Mak towarzyszy Wigilii od czasów przedchrześcijańskich, bo jego usypiające działanie miało otwierać most między światem żywych a duszami przodków, które w środku zimy, blisko Bożego Narodzenia, uznawano za szczególnie bliskie. Jedna makówka niesie ponad tysiąc drobnych ziaren, dlatego mak symbolizował też obfitość, płodność i pomyślność w nadchodzącym roku. Makaron z makiem, czyli ugotowany makaron ze słodką masą makową, to regionalna odpowiedź na tę symbolikę z Wielkopolski, Kujaw i okolic Łodzi, czyli terenów dawnego zaboru pruskiego. Tam ta potrawa pełni rolę, którą na wschodzie Polski odgrywa pszeniczna [kutia](/pl/rezepte/kutia). Świadomie nie jest to zwijana rolada drożdżowa jak [makowiec](/pl/rezepte/makowiec), którego technikę opisuje [technika makowca](/pl/blog/makowiec-technika), ani danie z twarogiem jak [makaron z serem](/pl/rezepte/makaron-z-serem).

## Zakupy i gotowanie

Krótki makaron jajeczny lub wstążki kupisz w markecie, do tego masło, cukier i mleko. Prawdziwym nośnikiem smaku jest mak niebieski, najlepiej świeżo mielony, który znajdziesz często w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Całe ziarna można też zmielić samodzielnie, ale trzeba to uczciwie napisać. Opcjonalnie pasują miód, rodzynki i skórka cytryny. Gdy brakuje mielonego maku, pomogą [zamienniki składników](/pl/blog/zamienniki-skladnikow), choć kakao jako zamiennik maku raczej się nie sprawdza.

Makaron powinien zostać al dente, podczas gdy mak krótko pęcznieje w gorącym płynie, a potem dobrze się odsącza. Wymieszany z cukrem i masłem tworzy smarowną masę, która ani nie cieknie, ani nie jest sucha jak piasek. Wszystko łącz na gorąco, bo zimny makaron gorzej przyjmuje smak, a wody z gotowania dodawaj oszczędnie, inaczej masa się rozwodni. Gorycz niemal zawsze pochodzi ze starego maku lub zbyt mocnego prażenia, dlatego warto sprawdzić datę produkcji. W przeciwieństwie do [makowca](/pl/rezepte/makowiec) nie ma tu etapu zwijania ani pieczenia, danie jest gotowe, gdy wszystko połączy się w garnku.

W niemieckich kuchniach makaron z makiem często ratuje 24 grudnia, gdy piekarnik jest już zajęty innymi daniami i nikt nie chce prowadzić ciasta drożdżowego: jeden garnek makaronu, jedna miska masy makowej, gotowe. Mak najlepiej trzymać zawsze pod ręką ze [sklepu polskiego](/pl/blog/sklep-polski-zakupy), dzieci mogą sypać i mieszać, a gorący garnek zostaje przy dorosłych. Wystarczy dobry zwykły makaron i świeży mak, a sąsiadem technicznym jest [technika makowca](/pl/blog/makowiec-technika).

## Przy stole

Ciepło na talerzach, często z cukrem pudrem, jako słodki element przy [menu wigilijnym](/pl/blog/menu-wigilijne) obok kompotu i ryby. Wyraźnie osobno zostają plastry ze spiralą, czyli [makowiec](/pl/rezepte/makowiec), oraz kremowy makaron z twarogiem, czyli [makaron z serem](/pl/rezepte/makaron-z-serem). Resztki smakują na zimno albo krótko podgrzane na maśle, ponownego mocnego gotowania lepiej im oszczędzić.

Mylenie makaronu z makiem z roladą [makowca](/pl/rezepte/makowiec) prowadzi do błędnego oczekiwania ciasta drożdżowego zamiast dania z makaronu. Podobnie myląca jest pomyłka z [makaronem z serem](/pl/rezepte/makaron-z-serem), gdzie rządzi twaróg, a nie mak. Zbyt sucha, piaszczysta masa zwykle wynika z za małej ilości płynu, a stary, gorzki mak potrafi zepsuć cały smak. Za dużo wody z gotowania z kolei zamienia kremową masę w rzadką zupkę.

Więcej miodu daje łagodniejszy smak, rodzynki zostają klasycznym dodatkiem, a skórka pomarańczy zamiast cytryny daje delikatniejszą nutę. Na zimno danie następnego dnia smakuje niemal jak deser. Rolada to [makowiec](/pl/rezepte/makowiec), pasta z twarogiem to [makaron z serem](/pl/rezepte/makaron-z-serem), a pszenica z makiem zamiast makaronu czeka w [kutii](/pl/rezepte/kutia). Do okazji pasuje [menu wigilijne](/pl/blog/menu-wigilijne), do masy makowej [technika makowca](/pl/blog/makowiec-technika), a zakupy ułatwią [sklep polski](/pl/blog/sklep-polski-zakupy) i [zamienniki składników](/pl/blog/zamienniki-skladnikow).', 'Makaron z makiem przepis | Makaron z makiem | Alemniam', 'Makaron z makiem: makaron z makiem, masłem i cukrem. Na Wigilię, dwujęzycznie, jasno osobno od makowca i makaronu z serem.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
